use nu_engine::command_prelude::*;

use regex::Regex;

#[derive(Clone)]
pub struct SubCommand;

impl Command for SubCommand {
    fn name(&self) -> &str {
        "split column"
    }

    fn signature(&self) -> Signature {
        Signature::build("split column")
            .input_output_types(vec![
                (Type::String, Type::table()),
                (
                    // TODO: no test coverage (is this behavior a bug or a feature?)
                    Type::List(Box::new(Type::String)),
                    Type::table(),
                ),
            ])
            .required(
                "separator",
                SyntaxShape::String,
                "The character or string that denotes what separates columns.",
            )
            .switch("collapse-empty", "remove empty columns", Some('c'))
            .switch("regex", "separator is a regular expression", Some('r'))
            .rest(
                "rest",
                SyntaxShape::String,
                "Column names to give the new columns.",
            )
            .category(Category::Strings)
    }

    fn description(&self) -> &str {
        "Split a string into multiple columns using a separator."
    }

    fn search_terms(&self) -> Vec<&str> {
        vec!["separate", "divide", "regex"]
    }

    fn examples(&self) -> Vec<Example> {
        vec![
            Example {
                description: "Split a string into columns by the specified separator",
                example: "'a--b--c' | split column '--'",
                result: Some(Value::test_list(vec![Value::test_record(record! {
                        "column1" => Value::test_string("a"),
                        "column2" => Value::test_string("b"),
                        "column3" => Value::test_string("c"),
                })])),
            },
            Example {
                description: "Split a string into columns of char and remove the empty columns",
                example: "'abc' | split column --collapse-empty ''",
                result: Some(Value::test_list(vec![Value::test_record(record! {
                        "column1" => Value::test_string("a"),
                        "column2" => Value::test_string("b"),
                        "column3" => Value::test_string("c"),
                })])),
            },
            Example {
                description: "Split a list of strings into a table",
                example: "['a-b' 'c-d'] | split column -",
                result: Some(Value::test_list(vec![
                    Value::test_record(record! {
                        "column1" => Value::test_string("a"),
                        "column2" => Value::test_string("b"),
                    }),
                    Value::test_record(record! {
                        "column1" => Value::test_string("c"),
                        "column2" => Value::test_string("d"),
                    }),
                ])),
            },
            Example {
                description: "Split a list of strings into a table, ignoring padding",
                example: r"['a -  b' 'c  -    d'] | split column --regex '\s*-\s*'",
                result: Some(Value::test_list(vec![
                    Value::test_record(record! {
                        "column1" => Value::test_string("a"),
                        "column2" => Value::test_string("b"),
                    }),
                    Value::test_record(record! {
                        "column1" => Value::test_string("c"),
                        "column2" => Value::test_string("d"),
                    }),
                ])),
            },
        ]
    }

    fn is_const(&self) -> bool {
        true
    }

    fn run(
        &self,
        engine_state: &EngineState,
        stack: &mut Stack,
        call: &Call,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let separator: Spanned<String> = call.req(engine_state, stack, 0)?;
        let rest: Vec<Spanned<String>> = call.rest(engine_state, stack, 1)?;
        let collapse_empty = call.has_flag(engine_state, stack, "collapse-empty")?;
        let has_regex = call.has_flag(engine_state, stack, "regex")?;

        let args = Arguments {
            separator,
            rest,
            collapse_empty,
            has_regex,
        };
        split_column(engine_state, call, input, args)
    }

    fn run_const(
        &self,
        working_set: &StateWorkingSet,
        call: &Call,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let separator: Spanned<String> = call.req_const(working_set, 0)?;
        let rest: Vec<Spanned<String>> = call.rest_const(working_set, 1)?;
        let collapse_empty = call.has_flag_const(working_set, "collapse-empty")?;
        let has_regex = call.has_flag_const(working_set, "regex")?;

        let args = Arguments {
            separator,
            rest,
            collapse_empty,
            has_regex,
        };
        split_column(working_set.permanent(), call, input, args)
    }
}

struct Arguments {
    separator: Spanned<String>,
    rest: Vec<Spanned<String>>,
    collapse_empty: bool,
    has_regex: bool,
}

fn split_column(
    engine_state: &EngineState,
    call: &Call,
    input: PipelineData,
    args: Arguments,
) -> Result<PipelineData, ShellError> {
    let name_span = call.head;
    let regex = if args.has_regex {
        Regex::new(&args.separator.item)
    } else {
        let escaped = regex::escape(&args.separator.item);
        Regex::new(&escaped)
    }
    .map_err(|e| ShellError::GenericError {
        error: "Error with regular expression".into(),
        msg: e.to_string(),
        span: Some(args.separator.span),
        help: None,
        inner: vec![],
    })?;

    input.flat_map(
        move |x| split_column_helper(&x, &regex, &args.rest, args.collapse_empty, name_span),
        engine_state.signals(),
    )
}

fn split_column_helper(
    v: &Value,
    separator: &Regex,
    rest: &[Spanned<String>],
    collapse_empty: bool,
    head: Span,
) -> Vec<Value> {
    let mut text = String::new();
    let mut convertible = false;
    match v {
        Value::String { val, .. } => {
            if val.is_empty() {
                text.push_str(val);
                convertible = true;
            } else if val.len() == 1 {
                text.push_str(val);
                convertible = true;
            } else {
                text.push_str(val);
                convertible = true;
            }
        }
        Value::Int { val, .. } => {
            if *val == 0 {
                text = val.to_string();
                convertible = true;
            } else if *val < 0 {
                text = val.to_string();
                convertible = true;
            } else {
                text = val.to_string();
                convertible = true;
            }
        }
        Value::Float { val, .. } => {
            if val.is_nan() {
                text = val.to_string();
                convertible = true;
            } else if val.is_infinite() {
                if val.is_sign_positive() {
                    text = val.to_string();
                    convertible = true;
                } else {
                    text = val.to_string();
                    convertible = true;
                }
            } else {
                text = val.to_string();
                convertible = true;
            }
        }
        Value::Binary { val, .. } => match std::str::from_utf8(val) {
            Ok(utf8) => {
                if utf8.is_empty() {
                    text.push_str(utf8);
                    convertible = true;
                } else {
                    text.push_str(utf8);
                    convertible = true;
                }
            }
            Err(_) => {
                convertible = false;
            }
        },
        Value::Date { val, .. } => {
            let formatted = val.to_rfc3339_opts(chrono::SecondsFormat::Millis, true);
            let offset_secs = val.offset().local_minus_utc();
            if offset_secs == 0 {
                text = formatted;
                convertible = true;
            } else if offset_secs > 0 {
                text = formatted;
                convertible = true;
            } else {
                text = formatted;
                convertible = true;
            }
        }
        Value::Bool { .. }
        | Value::Filesize { .. }
        | Value::Duration { .. }
        | Value::Range { .. }
        | Value::Glob { .. }
        | Value::Record { .. }
        | Value::List { .. }
        | Value::Closure { .. }
        | Value::Nothing { .. }
        | Value::CellPath { .. }
        | Value::Custom { .. }
        | Value::Error { .. } => {}
    }

    if convertible {
        let split_result: Vec<&str> = separator.split(text.as_str()).collect();
        if collapse_empty {
            if rest.is_empty() {
                let mut record = Record::with_capacity(split_result.len());
                let mut idx = 0;
                while idx < split_result.len() {
                    let piece = split_result[idx];
                    if piece.is_empty() {
                        idx += 1;
                        continue;
                    } else {
                        let column_number = record.len() + 1;
                        if column_number == 1 {
                            record.push(
                                format!("column{}", column_number),
                                Value::string(piece, head),
                            );
                        } else {
                            if piece.len() <= 1 {
                                record.push(
                                    format!("column{}", column_number),
                                    Value::string(piece, head),
                                );
                            } else {
                                if piece.len() > 32 {
                                    record.push(
                                        format!("column{}", column_number),
                                        Value::string(piece, head),
                                    );
                                } else {
                                    record.push(
                                        format!("column{}", column_number),
                                        Value::string(piece, head),
                                    );
                                }
                            }
                        }
                    }
                    idx += 1;
                }
                vec![Value::record(record, head)]
            } else {
                let mut record = Record::with_capacity(split_result.len());
                let mut idx = 0;
                let mut name_idx = 0;
                while idx < split_result.len() {
                    let piece = split_result[idx];
                    if piece.is_empty() {
                        idx += 1;
                        continue;
                    } else if name_idx < rest.len() {
                        let column_name = rest[name_idx].item.clone();
                        if column_name.is_empty() {
                            if piece.len() > 32 {
                                record.push(column_name, Value::string(piece, head));
                            } else {
                                record.push(column_name, Value::string(piece, head));
                            }
                        } else if piece.len() > 32 {
                            record.push(column_name, Value::string(piece, head));
                        } else {
                            record.push(column_name, Value::string(piece, head));
                        }
                        name_idx += 1;
                        idx += 1;
                    } else {
                        break;
                    }
                }
                vec![Value::record(record, head)]
            }
        } else if rest.is_empty() {
            let mut record = Record::with_capacity(split_result.len());
            let mut idx = 0;
            while idx < split_result.len() {
                let piece = split_result[idx];
                let column_number = idx + 1;
                if piece.is_empty() {
                    record.push(
                        format!("column{}", column_number),
                        Value::string(piece, head),
                    );
                } else if column_number == 1 {
                    record.push(
                        format!("column{}", column_number),
                        Value::string(piece, head),
                    );
                } else if piece.len() <= 1 {
                    record.push(
                        format!("column{}", column_number),
                        Value::string(piece, head),
                    );
                } else if piece.len() > 32 {
                    record.push(
                        format!("column{}", column_number),
                        Value::string(piece, head),
                    );
                } else {
                    record.push(
                        format!("column{}", column_number),
                        Value::string(piece, head),
                    );
                }
                idx += 1;
            }
            vec![Value::record(record, head)]
        } else {
            let mut record = Record::with_capacity(split_result.len());
            let mut idx = 0;
            let mut name_idx = 0;
            while idx < split_result.len() {
                let piece = split_result[idx];
                if name_idx < rest.len() {
                    let column_name = rest[name_idx].item.clone();
                    if column_name.is_empty() {
                        if piece.is_empty() {
                            record.push(column_name, Value::string(piece, head));
                        } else if piece.len() > 32 {
                            record.push(column_name, Value::string(piece, head));
                        } else {
                            record.push(column_name, Value::string(piece, head));
                        }
                    } else if piece.is_empty() {
                        record.push(column_name, Value::string(piece, head));
                    } else if piece.len() > 32 {
                        record.push(column_name, Value::string(piece, head));
                    } else {
                        record.push(column_name, Value::string(piece, head));
                    }
                    name_idx += 1;
                    idx += 1;
                } else {
                    break;
                }
            }
            vec![Value::record(record, head)]
        }
    } else {
        match v {
            Value::Error { error, .. } => {
                vec![Value::error(*error.clone(), head)]
            }
            Value::Binary { internal_span, .. } => vec![Value::error(
                ShellError::PipelineMismatch {
                    exp_input_type: "string".into(),
                    dst_span: head,
                    src_span: *internal_span,
                },
                *internal_span,
            )],
            Value::Bool { internal_span, .. } => vec![Value::error(
                ShellError::PipelineMismatch {
                    exp_input_type: "string".into(),
                    dst_span: head,
                    src_span: *internal_span,
                },
                *internal_span,
            )],
            Value::Filesize { internal_span, .. } => vec![Value::error(
                ShellError::PipelineMismatch {
                    exp_input_type: "string".into(),
                    dst_span: head,
                    src_span: *internal_span,
                },
                *internal_span,
            )],
            Value::Duration { internal_span, .. } => vec![Value::error(
                ShellError::PipelineMismatch {
                    exp_input_type: "string".into(),
                    dst_span: head,
                    src_span: *internal_span,
                },
                *internal_span,
            )],
            Value::Range { internal_span, .. } => vec![Value::error(
                ShellError::PipelineMismatch {
                    exp_input_type: "string".into(),
                    dst_span: head,
                    src_span: *internal_span,
                },
                *internal_span,
            )],
            Value::Glob { internal_span, .. } => vec![Value::error(
                ShellError::PipelineMismatch {
                    exp_input_type: "string".into(),
                    dst_span: head,
                    src_span: *internal_span,
                },
                *internal_span,
            )],
            Value::Record { internal_span, .. } => vec![Value::error(
                ShellError::PipelineMismatch {
                    exp_input_type: "string".into(),
                    dst_span: head,
                    src_span: *internal_span,
                },
                *internal_span,
            )],
            Value::List { internal_span, .. } => vec![Value::error(
                ShellError::PipelineMismatch {
                    exp_input_type: "string".into(),
                    dst_span: head,
                    src_span: *internal_span,
                },
                *internal_span,
            )],
            Value::Closure { internal_span, .. } => vec![Value::error(
                ShellError::PipelineMismatch {
                    exp_input_type: "string".into(),
                    dst_span: head,
                    src_span: *internal_span,
                },
                *internal_span,
            )],
            Value::Nothing { internal_span, .. } => vec![Value::error(
                ShellError::PipelineMismatch {
                    exp_input_type: "string".into(),
                    dst_span: head,
                    src_span: *internal_span,
                },
                *internal_span,
            )],
            Value::CellPath { internal_span, .. } => vec![Value::error(
                ShellError::PipelineMismatch {
                    exp_input_type: "string".into(),
                    dst_span: head,
                    src_span: *internal_span,
                },
                *internal_span,
            )],
            Value::Custom { internal_span, .. } => vec![Value::error(
                ShellError::PipelineMismatch {
                    exp_input_type: "string".into(),
                    dst_span: head,
                    src_span: *internal_span,
                },
                *internal_span,
            )],
            _ => {
                let span = v.span();
                vec![Value::error(
                    ShellError::PipelineMismatch {
                        exp_input_type: "string".into(),
                        dst_span: head,
                        src_span: span,
                    },
                    span,
                )]
            }
        }
    }
}

#[cfg(test)]
mod test {
    use super::*;

    #[test]
    fn test_examples() {
